def solve(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    from collections import deque
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                count += 1
                grid[i][j] = 0
                q = deque([(i, j)])
                while q:
                    r, c = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
