def solve(n, edges=None):
    import heapq
    try:
        # handle alternate calling conventions
        if edges is None:
            if isinstance(n, (list, tuple)) and len(n) == 2:
                n, edges = n[0], n[1]
            else:
                return []
        if isinstance(n, bool):
            return []
        # coerce n
        try:
            n = int(n)
        except:
            return []
        if n < 0:
            return []
        if edges is None:
            edges = []
        try:
            edgelist = list(edges)
        except:
            return []
        adj = [[] for _ in range(n)]
        indeg = [0]*n
        seen = set()
        for e in edgelist:
            try:
                a, b = e
                a = int(a); b = int(b)
            except:
                continue
            if a < 0 or a >= n or b < 0 or b >= n:
                continue
            if (a, b) in seen:
                continue
            seen.add((a, b))
            adj[a].append(b)
            indeg[b] += 1
        heap = [i for i in range(n) if indeg[i] == 0]
        heapq.heapify(heap)
        res = []
        while heap:
            u = heapq.heappop(heap)
            res.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    heapq.heappush(heap, v)
        if len(res) != n:
            return []
        return res
    except Exception:
        return []

