def solve(n, edges):
    import heapq
    adj=[[] for _ in range(n)]
    for e in edges:
        a,b,w=e
        adj[a].append((b,w))
        adj[b].append((a,w))
    INF=float('inf')
    dist=[INF]*n
    if n==0:
        return -1
    dist[0]=0
    h=[(0,0)]
    while h:
        d,u=heapq.heappop(h)
        if d!=dist[u]:
            continue
        if u==n-1:
            break
        for v,w in adj[u]:
            nd=d+w
            if nd<dist[v]:
                dist[v]=nd
                heapq.heappush(h,(nd,v))
    return -1 if dist[n-1]==INF else dist[n-1]

